const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

// 1. Verify shared webhook secret header
const expectedSecret = $env.LEAD_WEBHOOK_SECRET || '';
const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
if (!expectedSecret || providedSecret !== expectedSecret) {
  throw new Error('Unauthorized: invalid or missing X-Webhook-Secret header');
}

// 2. Reject honeypot spam silently
const honeypot = typeof body.website === 'string' ? body.website.trim() : '';
if (honeypot.length > 0) {
  return [];
}

// 3. Normalize email and extract domain
const rawEmail = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
if (!rawEmail || !rawEmail.includes('@')) {
  throw new Error('Validation failed: missing or malformed lead email');
}

const domain = rawEmail.split('@')[1].replace(/[^a-z0-9.-]/g, '');
const freeProviders = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com',
  'outlook.com', 'live.com', 'icloud.com', 'me.com',
  'proton.me', 'protonmail.com', 'aol.com'
]);

return [{
  json: {
    lead: {
      full_name: String(body.full_name || body.name || '').trim().slice(0, 120),
      email: rawEmail,
      domain,
      is_free_email: freeProviders.has(domain),
      company: String(body.company || '').trim().slice(0, 120),
      role: String(body.role || '').trim().slice(0, 120),
      budget_range: String(body.budget_range || 'unspecified').trim().slice(0, 64),
      message: String(body.message || '').trim().slice(0, 2000),
      source: String(body.source || 'web_form').trim().slice(0, 64),
      received_at: new Date().toISOString()
    }
  }
}];

const sanitized = $('Verify & Sanitize Lead').first().json.lead;
const incoming = $input.first().json;

let pageTitle = '';
let metaDescription = '';

const html = typeof incoming.data === 'string' ? incoming.data : '';
if (html.length > 0) {
  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (titleMatch) {
    pageTitle = titleMatch[1].replace(/\s+/g, ' ').trim().slice(0, 160);
  }
  const descMatch = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i)
    || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i);
  if (descMatch) {
    metaDescription = descMatch[1].replace(/\s+/g, ' ').trim().slice(0, 300);
  }
}

return [{
  json: {
    lead: sanitized,
    enrichment: {
      homepage_fetched: html.length > 0,
      page_title: pageTitle || 'unavailable',
      meta_description: metaDescription || 'unavailable'
    }
  }
}];

const context = $('Prepare AI Context').first().json;
const rawResponse = $input.first().json;
const content = rawResponse?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('AI qualification returned empty content');
}

const ai = JSON.parse(content);
const threshold = Number($env.AI_CONFIDENCE_THRESHOLD ?? 0.80);

return [{
  json: {
    lead: context.lead,
    enrichment: context.enrichment,
    ai,
    confidence_threshold: Number.isFinite(threshold) ? threshold : 0.80
  }
}];

